-- =============================================================================
-- darc_dok: DARC DOKs and special DOKs (QG Reference)
-- GENERATED by scripts/build.py from data/facts and data/SOURCE.json. Do not edit by hand.
-- Owner: Deutscher Amateur-Radio-Club e.V. (DARC). Document: DOK-Liste.pdf, SDOK_List.csv, edition DOK-Liste 2016-12-26; special DOKs as retrieved.
-- PREREQUISITE: QG ADIF's `adif` schema is loaded first (the foreign keys point into it),
-- with ADIF 3.1.7.
-- =============================================================================
BEGIN;
DROP SCHEMA IF EXISTS darc_dok CASCADE;
CREATE SCHEMA darc_dok;

-- Where every fact here came from: SOURCE.json (owner, document URL, SHA-256).
CREATE TABLE darc_dok.source (
    singleton boolean PRIMARY KEY DEFAULT TRUE CHECK (singleton),
    document  jsonb NOT NULL
);

CREATE TABLE darc_dok.code (
    list               text    NOT NULL,
    seq                integer NOT NULL,
    code               text    NOT NULL,
    name               text,
    valid_from         date,
    valid_to           date,
    replaced_by        text,
    attributes         jsonb,
    source             text    NOT NULL,
    transcription_note text,
    PRIMARY KEY (list, seq)
);
CREATE INDEX code_code ON darc_dok.code (code);

-- What each code covers, in ADIF's own codes. pas_key is ADIF's record key for the
-- subdivision (code.entity, e.g. 'QC.1'): ADIF's subdivision table has no other unique key.
CREATE TABLE darc_dok.cover (
    list         text    NOT NULL,
    seq          integer NOT NULL,
    n            integer NOT NULL,
    adif_version text    NOT NULL DEFAULT '3.1.7',
    dxcc         integer,
    pas          text,
    pas_key      text GENERATED ALWAYS AS (pas || '.' || dxcc::text) STORED,
    prefix       text,
    boundary     text,
    PRIMARY KEY (list, seq, n),
    FOREIGN KEY (list, seq) REFERENCES darc_dok.code (list, seq),
    FOREIGN KEY (adif_version, dxcc) REFERENCES adif.dxcc_entity_code (adif_version, entity_code),
    FOREIGN KEY (adif_version, pas_key) REFERENCES adif.primary_administrative_subdivision (adif_version, record_key)
);
CREATE INDEX cover_entity ON darc_dok.cover (dxcc, pas);


DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ionis_ro') THEN
  GRANT USAGE ON SCHEMA darc_dok TO ionis_ro;
  GRANT SELECT ON ALL TABLES IN SCHEMA darc_dok TO ionis_ro;
END IF; END $$;
COMMIT;
